"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["3789"],{31502(e){e.exports=JSON.parse('{"id":"V4-166","slug":"stewardship","term":"Stewardship","also_known_as":[],"difficulty":"Intermediate","definition":"Stewardship is the responsible management and oversight of investments by asset owners and asset managers on behalf of their clients and beneficiaries, including engaging with companies and voting at shareholder meetings to protect and increase long-term value.","explanation":["Stewardship goes beyond choosing which investments to buy and sell. It involves actively using the rights and influence that come with owning shares and other investments.","Stewardship activities include engaging with company management and boards on issues such as strategy, performance, governance, executive pay, climate change and social issues; voting at company meetings; working with other investors to raise concerns; and, if necessary, escalating issues through public statements or shareholder resolutions.","For example, a pension fund might meet a company\u2019s board to press for stronger climate targets and vote against the re-election of directors if it sees no progress.","Many countries have stewardship codes that set out expectations for investors. The UK Stewardship Code, first published in 2010 and revised several times, is one of the best known, and similar codes exist in Japan and many other markets. Signatories report on their stewardship activities and outcomes. Critics argue that some investors\u2019 stewardship is limited, while others question whether investors should pursue environmental or social goals."],"note":"","total":1725,"prev":{"slug":"statutory-accounts","term":"Statutory Accounts"},"next":{"slug":"stimulus","term":"Stimulus"}}')}}]);